--
-- Structure de la table `mouvement_stock`
--

DROP TABLE IF EXISTS `mouvement_stock`;
CREATE TABLE IF NOT EXISTS `mouvement_stock` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code_mouvement` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Réf. unique ex: MV-20260721-001',
  `produit_id` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `boutique_id` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `type_mouvement` enum('ENTREE_ACHAT','ENTREE_TRANSFERT','ENTREE_RETOUR_CLIENT','ENTREE_INVENTAIRE','SORTIE_VENTE','SORTIE_TRANSFERT','SORTIE_PERTE','SORTIE_INVENTAIRE') COLLATE utf8mb4_general_ci NOT NULL,
  `quantite` int NOT NULL,
  `stock_avant` int NOT NULL,
  `stock_apres` int NOT NULL,
  `prix_unitaire` decimal(12,2) NOT NULL DEFAULT '0.00',
  `reference_document` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `code_transfert` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Même valeur pour les deux lignes d''un transfert',
  `boutique_partenaire` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Boutique source ou destination du transfert',
  `statut_id` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `date_mouvement` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `utilisateur_id` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `commentaire` text COLLATE utf8mb4_general_ci,
  `etat` enum('VALIDE','ANNULE') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'VALIDE',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code_mouvement` (`code_mouvement`),
  KEY `idx_mvt_produit` (`produit_id`),
  KEY `idx_mvt_boutique` (`boutique_id`),
  KEY `idx_mvt_transfert` (`code_transfert`),
  KEY `idx_mvt_document` (`reference_document`),
  KEY `idx_mvt_date` (`date_mouvement`)
) ;

