--
-- Structure de la table `prix`
--

DROP TABLE IF EXISTS `prix`;
CREATE TABLE IF NOT EXISTS `prix` (
  `code_prix` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `produit_id` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `boutique_id` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'NULL = prix global',
  `titre_prix` enum('DETAILS','DEMI-GROS','GROS') COLLATE utf8mb4_general_ci DEFAULT 'DETAILS',
  `quantite_min` int NOT NULL DEFAULT '1',
  `quantite_max` int DEFAULT NULL COMMENT 'NULL = pas de limite haute',
  `prix_unitaire` decimal(12,2) NOT NULL,
  `etat_prix` enum('Actif','Inactif') COLLATE utf8mb4_general_ci DEFAULT 'Actif',
  PRIMARY KEY (`code_prix`),
  UNIQUE KEY `uk_prix_produit_boutique_type_min` (`produit_id`,`boutique_id`,`titre_prix`,`quantite_min`),
  KEY `idx_prix_produit` (`produit_id`),
  KEY `idx_prix_boutique` (`boutique_id`),
  KEY `idx_prix_palier` (`produit_id`,`quantite_min`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

